from collections import deque


def transform(grid):
    """Expand each 2 marker inside a 3-colored panel into a 3x3 halo of 1s."""
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            boxes.append((min(y for y,x in cells), max(y for y,x in cells),
                          min(x for y,x in cells), max(x for y,x in cells)))

    out = [row[:] for row in grid]
    # Treat each 3-panel as its rectangular extent: embedded 2 markers,
    # including those in missing/irregular cells within that extent, are seeds.
    centers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                          for r0, r1, c0, c1 in boxes)]
    for r, c in centers:
        for y in range(max(0, r-1), min(h, r+2)):
            for x in range(max(0, c-1), min(w, c+2)):
                if (y, x) != (r, c):
                    out[y][x] = 1
    # Overlapping halos never erase the red marker at their centers.
    for r, c in centers:
        out[r][c] = 2
    return out
